namespace Idasletten.Models;

public class TournamentTeam
{
    public Guid Id { get; set; } = Guid.NewGuid();

    /// <summary>Autogenerated: "Team 1", "Team 2", …</summary>
    public string Name { get; set; } = null!;

    /// <summary>Autogenerated: 1, 2, …</summary>
    public int Number { get; set; }

    public Guid TournamentId { get; set; }
    public Tournament Tournament { get; set; } = null!;

    public ICollection<TeamPlayer> Players { get; set; } = new List<TeamPlayer>();
    public ICollection<TournamentTeamMatchResult> Results { get; set; } = new List<TournamentTeamMatchResult>();
}

/// <summary>Membership of a <see cref="TournamentPlayer"/> on a <see cref="TournamentTeam"/>.</summary>
public class TeamPlayer
{
    public Guid TeamId { get; set; }
    public TournamentTeam Team { get; set; } = null!;

    public Guid TournamentPlayerId { get; set; }
    public TournamentPlayer Player { get; set; } = null!;
}
